    if String.contains?(filename, ["\r", "\n", <<0>>]) do
      raise ArgumentError,
            "multipart filename must not contain CR, LF, or NUL characters (got: #{inspect(filename)})"
    end

    # Gap W2: validate the field name to reject CR/LF/NUL header
    # injection in addition to escaping embedded quotes / backslashes.
    escaped_name = sanitize_multipart_field_name(name)

    if ascii?(filename) do
      "Content-Disposition: form-data; name=\"#{escaped_name}\"; filename=\"#{escape_quoted(filename)}\""
    else
      ascii_fallback = filename |> to_ascii_fallback() |> escape_quoted()
      encoded = URI.encode(filename, &URI.char_unreserved?/1)

      "Content-Disposition: form-data; name=\"#{escaped_name}\"; " <>
        "filename=\"#{ascii_fallback}\"; filename*=UTF-8''#{encoded}"
    end
  end

  defp escape_quoted(value) do
    value
    |> String.replace("\\", "\\\\")
    |> String.replace("\"", "\\\"")
  end

  defp ascii?(binary) do
    :binary.bin_to_list(binary) |> Enum.all?(fn b -> b < 128 end)
  end

  defp to_ascii_fallback(filename) do
    filename
    |> :binary.bin_to_list()
    |> Enum.map(fn
      b when b < 128 -> b
      _ -> ?_
    end)
    |> :binary.list_to_bin()
  end

  defp guess_mime_type(filename) when is_binary(filename) do
    if Code.ensure_loaded?(MIME) and function_exported?(MIME, :from_path, 1) do
      try do
        MIME.from_path(filename) || "application/octet-stream"
      rescue
        _ -> "application/octet-stream"
      end
    else
      "application/octet-stream"
    end
  end

  defp guess_mime_type(_) do
    "application/octet-stream"
  end

  # Gap BE+BF: response header keys are normalised to lowercase so callers can
  # look them up consistently regardless of the casing the server used (HTTP
  # header names are case-insensitive per RFC 7230 section 3.2, and HTTP/2
  # mandates lowercase on the wire). Repeated header lines are joined with
  # ", " to preserve order per RFC 7230 section 3.2.2. The joined form is
  # not directly parseable for Set-Cookie; callers that need structured
  # cookie access should split on ", " with care or use a dedicated cookie
  # library such as `:cookies` or parse the original `Req.Response.headers/0`
  # map themselves.
  defp normalize_headers(headers) do
    Enum.reduce(headers, %{}, fn {key, values}, acc ->
      value =
        case values do
          list when is_list(list) -> Enum.join(list, ", ")
          v when is_binary(v) -> v
          _ -> to_string(values)
        end

      Map.put(acc, String.downcase(to_string(key)), value)
    end)
  end

  defp is_text_content_type(content_type) do
    media_type =
      content_type
      |> String.split(";")
      |> List.first()
      |> String.trim()
      |> String.downcase()

    cond do
      media_type == "" -> true
      String.starts_with?(media_type, "text/") -> true
      media_type in ["application/json", "application/xml", "application/javascript"] -> true
      String.ends_with?(media_type, "+json") -> true
      String.ends_with?(media_type, "+xml") -> true
      true -> false
    end
  end

  defp generate_uuid do
    <<a::32, b::16, _::4, c::12, _::2, d::62>> = :crypto.strong_rand_bytes(16)

    :io_lib.format(
      "~8.16.0b-~4.16.0b-4~3.16.0b-~4.16.0b-~12.16.0b",
      [a, b, c &&& 0xFFF, (d >>> 48 &&& 0x3FFF) ||| 0x8000, d &&& 0xFFFFFFFFFFFF]
    )
    |> to_string()
  end
end
